// Kiểm tra câu trả lời của Agent trước khi gửi khách (guardrail đầu ra)
const ctx = $('Chuẩn hoá tin nhắn').first().json;
let reply = String($json.output ?? '').trim();
// Telegram gửi văn bản thuần (không parse_mode), nên bỏ dấu markdown nếu model vẫn dùng
reply = reply.replace(/\*\*(.+?)\*\*/g, '$1').replace(/^#+\s*/gm, '');
reply = reply.charAt(0).toUpperCase() + reply.slice(1);

let usedFallback = false;
if (!reply || reply.includes('{{') || reply.length > 3500) {
  usedFallback = true;
  reply = 'Xin lỗi anh/chị, chúng tôi chưa trả lời được câu này. Chúng tôi đã báo nhân viên tư vấn để liên hệ lại anh/chị. Anh/chị có thể để lại số điện thoại để nhân viên gọi nhanh hơn nhé.';
}
// Bot không trả lời được thì chuyển cho người (human-in-the-loop)
return [{ json: { chatId: ctx.chatId, reply, route: 'AGENT', usedFallback, escalate: usedFallback, reason: usedFallback ? 'Bot chưa trả lời được câu hỏi của khách' : '' } }];

// Guardrails phát hiện tin lừa bot bỏ qua quy tắc (jailbreak / prompt injection): không đưa vào Agent
return [{ json: {
  route: 'BLOCKED',
  reply: 'Xin lỗi anh/chị, chúng tôi chỉ hỗ trợ tìm nhà, đặt lịch xem nhà và giải đáp quy trình mua nhà của văn phòng. Anh/chị vui lòng hỏi về các nội dung này nhé.',
  usedFallback: false, escalate: false,
} }];

// Khách muốn gặp người thật: không để bot tự xử lý (human-in-the-loop, chuyển ca khó cho nhân viên)
return [{ json: {
  route: 'STAFF',
  reply: 'Chúng tôi đã báo nhân viên tư vấn, nhân viên sẽ liên hệ anh/chị sớm nhất có thể. Anh/chị có thể để lại số điện thoại để nhân viên gọi lại nhanh hơn nhé.',
  usedFallback: false, escalate: true, reason: 'Khách muốn gặp nhân viên hoặc phàn nàn',
} }];

// Câu hỏi không liên quan tới nhà đất: trả lời mẫu, không tốn lượt Agent
return [{ json: {
  route: 'OUT_OF_SCOPE',
  reply: 'Chúng tôi là trợ lý của văn phòng bất động sản nên chỉ hỗ trợ tìm nhà, đặt lịch xem nhà và giải đáp quy trình mua nhà. Anh/chị cần tìm căn nào, ở khu vực nào ạ?',
  usedFallback: false, escalate: false,
} }];

// Đầu vào cho sub-workflow Thông báo nhân viên (email + Telegram nhóm sale)
const msg = $('Chuẩn hoá tin nhắn').first().json;
const cfg = $('Cấu hình').first().json;
const actions = [];
if (msg.username) actions.push({ label: 'Nhắn khách trên Telegram', url: 'https://t.me/' + msg.username });
return [{ json: {
  title: $json.route === 'STAFF' ? 'Khách Telegram muốn gặp nhân viên' : 'Bot chưa trả lời được khách Telegram',
  fields: [
    { icon: '👤', label: 'Tên Telegram', value: msg.firstName || '(không có)' },
    { icon: '💬', label: 'Username', value: msg.username ? '@' + msg.username : '(khách chưa đặt username)' },
    { icon: '📌', label: 'Lý do', value: $json.reason },
  ],
  message: 'Tin nhắn của khách: ' + msg.text,
  note: msg.username ? 'Bấm nút để nhắn trực tiếp cho khách.' : 'Khách chưa có username: chờ khách để lại số điện thoại trong bot, hoặc xem lịch sử chat ở n8n (Executions của luồng 6).',
  actions,
} }];

// Gom các nhánh về một dạng chung trước khi gửi khách và ghi log
const msg = $('Chuẩn hoá tin nhắn').first().json;
const notified = $('Báo nhân viên').isExecuted;
// first(0): nhánh "true" của If (node này cũng nối thẳng vào nhánh "false")
const base = notified ? $('Cần báo nhân viên?').first(0).json : $json;
let staffNotified = false;
if (notified) {
  const r = $('Báo nhân viên').first().json;
  staffNotified = !r.error && (r.telegramSent === true || r.emailSent === true);
}
let reply = String(base.reply ?? '');
// Đã hứa "đã báo nhân viên" mà báo không được thì nói thật với khách
if (base.escalate && !staffNotified) {
  reply = 'Hiện chúng tôi chưa kết nối được nhân viên. Anh/chị vui lòng để lại số điện thoại để nhân viên gọi lại, hoặc đặt lịch xem nhà trên web: ' + $('Cấu hình').first().json.publicWebUrl;
}
return [{ json: {
  chatId: msg.chatId,
  reply,
  route: base.route || 'COMMAND',
  question: msg.text,
  usedFallback: base.usedFallback === true,
  escalated: base.escalate === true,
  staffNotified,
} }];
